import { findById } from './users.js';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

class TaskManager {
  private tasks = new Map<string, Task>();
  private cache: { invalidate: (key: string) => void } | null = null;
  private audit: { record: (entry: { action: string; userId: string; taskId?: string; details?: string; timestamp: number }) => void } | null = null;

  setCache(cache: { invalidate: (key: string) => void }) {
    this.cache = cache;
  }

  setAudit(audit: { record: (entry: { action: string; userId: string; taskId?: string; details?: string; timestamp: number }) => void }) {
    this.audit = audit;
  }

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    if (!input.title || input.title.trim() === '') {
      throw new Error('Title must not be empty');
    }
    findById(input.createdBy);
    findById(input.assignee);

    const task: Task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };
    this.tasks.set(task.id, task);
    this.audit?.record({ action: 'create', userId: input.createdBy, taskId: task.id, timestamp: Date.now() });
    return task;
  }

  getTask(id: string): Task | null {
    return this.tasks.get(id) ?? null;
  }

  updateStatus(id: string, status: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const allowed: Record<string, string[]> = {
      open: ['in_progress'],
      in_progress: ['done', 'open'],
      done: ['in_progress'],
    };
    if (!allowed[task.status].includes(status)) {
      throw new Error(`Invalid status transition: ${task.status} -> ${status}`);
    }

    task.status = status;
    this.cache?.invalidate(id);
    this.audit?.record({ action: 'status_change', userId: task.createdBy, taskId: task.id, timestamp: Date.now() });
    return task;
  }

  delete(id: string, userId: string): boolean {
    const task = this.tasks.get(id);
    if (!task) return false;

    this.audit?.record({ action: 'delete', userId, taskId: id, timestamp: Date.now() });
    this.cache?.invalidate(id);
    this.tasks.delete(id);
    return true;
  }

  listByUser(userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId,
    );
  }

  all(): Task[] {
    return Array.from(this.tasks.values());
  }

  clear() {
    this.tasks.clear();
  }
}

export const taskManager = new TaskManager();
", "path": "src/tasks.ts"}

