{"content": "// CSV exporter.
// Must check permission, build CSV, record audit.

import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

function escapeCsv(value: string): string {
  if (value.includes(',') || value.includes('"') || value.includes('\n')) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error('Permission denied: export requires admin role');
  }

  const tasks = taskManager.all();
  const headers = ['id', 'title', 'status', 'assignee', 'createdAt'];
  const lines = [headers.join(',')];

  for (const task of tasks) {
    const row = [
      task.id,
      task.title,
      task.status,
      task.assignee,
      String(task.createdAt),
    ].map(escapeCsv);
    lines.push(row.join(','));
  }

  record({ action: 'export', userId, timestamp: Date.now() });
  return lines.join('\n');
}
", "path": "src/exporter.ts"}

