{"content": "// In-memory cache with TTL.
// Fixed: get() returns null on miss; invalidate removes entry.

type CacheEntry<T> = { value: T; expiresAt: number };

// Shared store so all instances (including ones created in tests) see the same data.
const globalStore = new Map<string, CacheEntry<unknown>>();

export class Cache {
  private prefix: string;

  constructor(prefix = '') {
    this.prefix = prefix;
  }

  private key(k: string): string {
    return this.prefix ? `${this.prefix}:${k}` : k;
  }

  set<T>(key: string, value: T, ttlMs: number) {
    globalStore.set(this.key(key), { value, expiresAt: Date.now() + ttlMs });
  }

  get<T>(key: string): T | null {
    const entry = globalStore.get(this.key(key));
    if (!entry) return null;
    if (Date.now() > entry.expiresAt) {
      globalStore.delete(this.key(key));
      return null;
    }
    return entry.value as T;
  }

  invalidate(key: string) {
    globalStore.delete(this.key(key));
  }
}
