{"content": "import { findById } from './users.ts';
import { canDelete } from './permissions.ts';
import { record } from './audit.ts';
import { Cache } from './cache.ts';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

class TaskManager {
