    const task = this.tasks.get(id);
    if (!task) return null;

    const allowed: Record<string, string[]> = {
      open: ['in_progress'],
      in_progress: ['done', 'open'],
      done: ['in_progress'],
    };
    if (!allowed[task.status].includes(status)) {
      throw new Error(`Invalid status transition: ${task.status} -> ${status}`);
    }

    task.status = status;
    this.cache.invalidate(id);
    record({ action: 'status_change', userId: task.createdBy, taskId: task.id, timestamp: Date.now() });
    return task;
  }

